function todayKey(){ return new Date().toISOString().slice(0,10); }
function cloneInitial(){ return JSON.parse(JSON.stringify(initialData)); }
function load(){ try{const raw=localStorage.getItem("edulink-eswatini-data-v3"); const d=raw?JSON.parse(raw):cloneInitial(); d.schools=(d.schools||[]).map(s=>({...s,image:s.image||schoolImage(s.name),address:s.address||s.location||"Eswatini"})); d.schools.forEach(s=>{s.staff=(s.staff||[]).map(st=>({...st,photo:st.photo||staffImage(st.name)}));}); d.parentFeedback=d.parentFeedback||[]; d.suggestions=d.suggestions||[]; d.attendanceRecords=d.attendanceRecords||{}; return d;}catch{return cloneInitial();} }
function save(data){try{localStorage.setItem("edulink-eswatini-data-v3",JSON.stringify(data));}catch{}}
function totalSpaces(spaces={}){return Object.values(spaces).reduce((a,b)=>a+Number(b||0),0)}
function average(student){const vals=Object.values(student.subjects||{}).flatMap(x=>[Number(x.test||0),Number(x.exam||0)]);return vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0}
function aggregate(student){return Object.values(student.subjects||{}).reduce((a,x)=>a+Number(x.test||0)+Number(x.exam||0),0)}
function initials(name){return name.split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase()}
function schoolImage(name){const label=encodeURIComponent(name||"EduLink School");return `data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" width="900" height="500" viewBox="0 0 900 500"><defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="%230b2d45"/><stop offset="1" stop-color="%23b58a3a"/></linearGradient></defs><rect width="900" height="500" fill="url(%23g)"/><rect x="120" y="180" width="660" height="210" rx="12" fill="white" opacity=".94"/><path d="M90 185 L450 75 L810 185 Z" fill="%23f4f0e6"/><rect x="415" y="250" width="70" height="140" fill="%230b2d45"/><g fill="%23b58a3a"><rect x="180" y="235" width="70" height="55"/><rect x="310" y="235" width="70" height="55"/><rect x="520" y="235" width="70" height="55"/><rect x="650" y="235" width="70" height="55"/></g><text x="450" y="450" text-anchor="middle" font-family="Arial" font-size="28" fill="white">${label}</text></svg>`}
function staffImage(name){const label=encodeURIComponent(initials(name));return `data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="300" height="300" fill="%230b2d45"/><circle cx="150" cy="105" r="58" fill="%23d9a06c"/><path d="M85 285c10-72 45-105 65-105s55 33 65 105" fill="%23f2f2f2"/><text x="150" y="270" text-anchor="middle" font-family="Arial" font-weight="700" font-size="32" fill="%23b58a3a">${label}</text></svg>`}

function App(){
  const [data,setData]=useState(load);
  const [user,setUser]=useState(null);
  const [page,setPage]=useState("home");
  const [mobile,setMobile]=useState(false);
  const update=(next)=>{setData(next);save(next)};
  if(!user) return <Public data={data} update={update} page={page} setPage={setPage} onLogin={setUser}/>;
  const allowed=roleAccess[user.role]||[];
  const currentSchool=user.schoolId?data.schools.find(s=>s.id===user.schoolId):null;
  return <div className="portal">
    <aside className={mobile?"sidebar open":"sidebar"}>
      <div className="logo"><span className="logoMark"><ShieldCheck size={21}/></span><div>EduLink <b>ESWATINI</b></div></div>
      <div className="rolePill"><span></span>{user.role}</div>
      <nav>{allowed.map(key=>{const [label,Icon]=nav[key];return <button key={key} className={page===key?"active":""} onClick={()=>{setPage(key);setMobile(false)}}><Icon size={18}/>{label}</button>})}</nav>
      <div className="sideBottom"><div className="securityNote"><ShieldCheck size={15}/><span>Role-based access enabled</span></div><button className="signout" onClick={()=>{setUser(null);setPage("home")}}><LogOut size={17}/>Sign out</button></div>
    </aside>
    <main className="workspace">
      <header className="topbar"><button className="mobileMenu" onClick={()=>setMobile(!mobile)}>{mobile?<X/>:<Menu/>}</button><div><span className="crumb">EduLink Eswatini</span><h2>{nav[page]?.[0]||"Overview"}</h2></div><div className="profile"><span className="avatar">{initials(user.name)}</span><div><b>{user.name}</b><small>{user.role}{currentSchool?` • ${currentSchool.name}`:""}</small></div><ChevronDown size={16}/></div></header>
      <div className="pageArea"><Page page={page} user={user} data={data} update={update} setPage={setPage}/></div>
    </main>
  </div>;
}

function Public({data,update,page,setPage,onLogin}){
  if(page==="login") return <Login setPage={setPage} onLogin={(u)=>{onLogin(u);setPage("overview")}}/>;
  if(page==="register-school") return <SchoolRegistration data={data} update={update} setPage={setPage}/>;
  if(page==="register-profile") return <ProfileRegistration data={data} update={update} setPage={setPage}/>;
  if(page==="directory") return <PublicDirectory data={data} setPage={setPage}/>;
  return <Landing setPage={setPage} data={data}/>;
}

function PublicHeader({setPage}){return <header className="publicHeader"><div className="logo publicLogo"><span className="logoMark"><ShieldCheck size={21}/></span><div>EduLink <b>ESWATINI</b></div></div><nav><button onClick={()=>setPage("home")}>Home</button><button onClick={()=>setPage("directory")}>Find a School</button><button onClick={()=>setPage("register-school")}>Register School</button><button className="loginButton" onClick={()=>setPage("login")}><LogIn size={16}/>Login</button></nav></header>}

function Landing({setPage,data}){return <div className="publicSite"><PublicHeader setPage={setPage}/><section className="heroPublic"><div className="heroText"><div className="eyebrow">A DIGITAL EDUCATION PLATFORM FOR ESWATINI</div><h1>Connecting <span>schools, families</span> and opportunity.</h1><p>EduLink brings school discovery, applications, academic progress, fees and communication into one professional, role-based platform.</p><div className="heroActions"><button className="goldButton" onClick={()=>setPage("directory")}>Find a School <ArrowRight size={17}/></button><button className="outlineButton" onClick={()=>setPage("register-school")}>Register Your School</button></div><div className="trustRow"><div><CheckCircle2 size={17}/><span>Role-based access</span></div><div><FileCheck2 size={17}/><span>Digital applications</span></div><div><ShieldCheck size={17}/><span>Controlled information</span></div></div></div><div className="heroVisual"><div className="crest"><GraduationCap size={44}/><strong>EDULINK</strong><small>ESWATINI</small></div><div className="visualCard vc1"><School size={19}/><div><b>{data.schools.length} approved schools</b><span>in the demo directory</span></div></div><div className="visualCard vc2"><Users size={19}/><div><b>Connected roles</b><span>Parents • Staff • Admin</span></div></div><div className="visualCard vc3"><Award size={19}/><div><b>EGCSE-inspired</b><span>professional visual language</span></div></div></div></section><section className="publicStats"><div><b>{data.schools.length}</b><span>Approved schools</span></div><div><b>{data.students.length}</b><span>Demo students</span></div><div><b>7</b><span>Portal roles</span></div><div><b>24/7</b><span>Digital access</span></div></section><section className="publicFeatures"><div className="sectionIntro"><div className="eyebrow">WHAT EDULINK CONNECTS</div><h2>Designed around how schools actually operate.</h2><p>Each role sees the information and actions relevant to its responsibility.</p></div><div className="featureGrid"><Feature icon={School} title="School discovery" text="Parents can search approved schools, view available spaces and start an application."/><Feature icon={ClipboardList} title="Admissions" text="Applications, supporting documents and decisions move through the correct school workflow."/><Feature icon={BarChart3} title="Academic progress" text="Teachers enter only the subjects they teach; principals can review school performance."/><Feature icon={Wallet} title="Fees & receipts" text="Accountants manage balances and verify parent-submitted receipts without academic data."/><Feature icon={Bell} title="Communication" text="Secretaries and school leadership can keep families informed through notifications."/><Feature icon={ShieldCheck} title="Controlled access" text="Parents see only their own children; platform administration stays separate from school academics."/></div></section><footer className="publicFooter"><div className="logo"><span className="logoMark"><ShieldCheck size={19}/></span><div>EduLink <b>ESWATINI</b></div></div><span>Presentation prototype • Demo data only • By Leo Mnisi</span></footer></div>}
function Feature({icon:Icon,title,text}){return <article className="feature"><span className="featureIcon"><Icon size={21}/></span><h3>{title}</h3><p>{text}</p></article>}

function Login({setPage,onLogin}){const [email,setEmail]=useState("");const [pw,setPw]=useState("");const [error,setError]=useState("");const roles=["Parent","Teacher","Principal","Deputy Principal","Accountant","Secretary","System Admin"];const demoEmail={Parent:"parent@demo.sz",Teacher:"teacher@demo.sz",Principal:"principal@demo.sz","Deputy Principal":"deputy@demo.sz",Accountant:"accountant@demo.sz",Secretary:"secretary@demo.sz","System Admin":"admin@demo.sz"};return <div className="authPage"><div className="authShell"><div className="authBrand"><span className="logoMark"><ShieldCheck/></span><div>EduLink <b>ESWATINI</b></div></div><div className="authHead"><div className="eyebrow">SECURE ROLE-BASED ACCESS</div><h1>Sign in to EduLink</h1><p>Use one login page. Your account determines which portal you can access.</p></div><div className="roleChooser">{roles.map(r=><button key={r} onClick={()=>{setEmail(demoEmail[r]);setPw(PASSWORD);setError("")}}>{r}</button>)}</div><label>Email address<input value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>Password<input type="password" value={pw} onChange={e=>setPw(e.target.value)} placeholder="Password"/></label>{error&&<div className="errorBox"><AlertCircle size={17}/>{error}</div>}<button className="goldButton full" onClick={()=>{const a=accounts[email.trim().toLowerCase()];if(a&&pw===PASSWORD)onLogin({...a,email:email.trim().toLowerCase()});else setError("Login failed. Select a role above or use a valid demo account." )}}>Login <ArrowRight size={17}/></button><div className="authLinks"><button onClick={()=>setPage("register-profile")}>Create a profile</button><button onClick={()=>setPage("home")}>Back to home</button></div><div className="demoHint"><b>Presentation demo</b><span>Select a role above. Password for all demo accounts: <strong>demo123</strong></span></div></div></div>}

function SchoolRegistration({data,update,setPage}){const [form,setForm]=useState({name:"",centre:"",location:"",address:"",type:"High School",email:"",phone:"",principal:"",deputy:"",staff:""});const [done,setDone]=useState(false);const set=(k,v)=>setForm({...form,[k]:v});function submit(){if(!form.name||!form.centre||!form.location||!form.principal){alert("Please complete the school name, Centre Number, location and principal.");return}const staff=form.staff.split("\n").map(x=>x.trim()).filter(Boolean).map((line,i)=>{const [name,role="Teacher"]=line.split("|").map(x=>x.trim());return {id:"REG-"+Date.now()+i,name,role,email:""}});const school={id:"P-"+Date.now(),name:form.name,centre:form.centre,location:form.location,address:form.address,type:form.type,email:form.email,phone:form.phone,image:schoolImage(form.name),fees:0,status:"PENDING",admission:"CLOSED",spaces:{},staff:[{id:"REG-P",name:form.principal,role:"Principal",email:""},...(form.deputy?[{id:"REG-D",name:form.deputy,role:"Deputy Principal",email:""}]:[]),...staff]};update({...data,pendingSchools:[...data.pendingSchools,school]});setDone(true)}return <div className="formPage"><div className="formShell"><div className="authBrand"><span className="logoMark"><School/></span><div>EduLink <b>ESWATINI</b></div></div>{done?<Success title="School registration submitted" text="The System Admin will verify that the school exists and that the submitted information is truthful before approving or rejecting it." setPage={setPage}/>:<><div className="authHead"><div className="eyebrow">SCHOOL ONBOARDING</div><h1>Register a school</h1><p>Provide the school information first. Include the principal, deputy and staff so staff profiles can later be matched to the registered school.</p></div><div className="formSection"><h3>School information</h3><div className="twoCol"><label>School name*<input value={form.name} onChange={e=>set("name",e.target.value)}/></label><label>Centre Number*<input value={form.centre} onChange={e=>set("centre",e.target.value)}/></label><label>Location*<input value={form.location} onChange={e=>set("location",e.target.value)}/></label><label>Address<input value={form.address} onChange={e=>set("address",e.target.value)}/></label><label>School type<select value={form.type} onChange={e=>set("type",e.target.value)}><option>High School</option><option>Primary School</option><option>Combined School</option></select></label><label>Email<input type="email" value={form.email} onChange={e=>set("email",e.target.value)}/></label><label>Phone<input value={form.phone} onChange={e=>set("phone",e.target.value)}/></label></div></div><div className="formSection"><h3>School leadership</h3><div className="twoCol"><label>Principal name*<input value={form.principal} onChange={e=>set("principal",e.target.value)}/></label><label>Deputy principal name<input value={form.deputy} onChange={e=>set("deputy",e.target.value)}/></label></div></div><div className="formSection"><h3>Staff list</h3><p className="help">One staff member per line: <b>Name | Role</b>. Roles: Teacher, Principal, Deputy Principal, Accountant, Secretary.</p><textarea value={form.staff} onChange={e=>set("staff",e.target.value)} placeholder={'Example:\nMs. P. Mamba | Accountant\nMrs. S. Hlophe | Secretary\nMr. T. Dlamini | Teacher'}/></div><div className="formActions"><button className="outlineButton" onClick={()=>setPage("home")}>Cancel</button><button className="goldButton" onClick={submit}>Submit for Admin verification <ArrowRight size={17}/></button></div></>}</div></div>}

function ProfileRegistration({data,update,setPage}){const [form,setForm]=useState({name:"",email:"",role:"Parent",schoolId:"",subjects:"",grades:""});const [done,setDone]=useState(false);const set=(k,v)=>setForm({...form,[k]:v});function submit(){if(!form.name||!form.email){alert("Name and email are required.");return}if(form.role!=="Parent"&&!form.schoolId){alert("Staff must select the school they are from.");return}const school=data.schools.find(s=>s.id===form.schoolId);if(form.role!=="Parent"&&school){const match=school.staff.some(s=>s.name.toLowerCase()===form.name.toLowerCase()&&s.role===form.role);if(!match){alert("The name and role could not be matched to the staff list registered by the school.");return}}setDone(true)}return <div className="formPage"><div className="formShell narrow"><div className="authBrand"><span className="logoMark"><UserPlus/></span><div>EduLink <b>ESWATINI</b></div></div>{done?<Success title="Profile submitted" text="For a real deployment, verified accounts would receive secure login credentials. This presentation prototype demonstrates the verification workflow." setPage={setPage}/>:<><div className="authHead"><div className="eyebrow">PROFILE REGISTRATION</div><h1>Create your profile</h1><p>Everyone creates a profile. Staff must identify their school; the submitted name and role must match the school's registered staff list before credentials are issued.</p></div><label>Full name<input value={form.name} onChange={e=>set("name",e.target.value)}/></label><label>Email<input value={form.email} onChange={e=>set("email",e.target.value)}/></label><label>Role<select value={form.role} onChange={e=>set("role",e.target.value)}><option>Parent</option><option>Teacher</option><option>Principal</option><option>Deputy Principal</option><option>Accountant</option><option>Secretary</option></select></label>{form.role!=="Parent"&&<><label>School<select value={form.schoolId} onChange={e=>set("schoolId",e.target.value)}><option value="">Select your school</option>{data.schools.filter(s=>s.status==="APPROVED").map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>{form.role==="Teacher"&&<div className="twoCol"><label>Subjects<input value={form.subjects} onChange={e=>set("subjects",e.target.value)} placeholder="Mathematics, English"/></label><label>Grades / Forms<input value={form.grades} onChange={e=>set("grades",e.target.value)} placeholder="Form 1, Form 2"/></label></div>}</>}<button className="goldButton full" onClick={submit}>Create profile <ArrowRight size={17}/></button><button className="textButton" onClick={()=>setPage("login")}>Back to login</button></>}</div></div>}
function Success({title,text,setPage}){return <div className="successPanel"><CheckCircle2 size={46}/><h2>{title}</h2><p>{text}</p><button className="goldButton" onClick={()=>setPage("home")}>Return home</button></div>}

function PublicDirectory({data,setPage}){const [q,setQ]=useState("");const schools=data.schools.filter(s=>s.status==="APPROVED"&&(`${s.name} ${s.centre} ${s.location}`.toLowerCase().includes(q.toLowerCase())));return <div className="publicSite"><PublicHeader setPage={setPage}/><section className="directoryPage"><div className="sectionIntro"><div className="eyebrow">APPROVED SCHOOL DIRECTORY</div><h1>Find a school</h1><p>Search by school name, Centre Number or location. Parents sign in before starting an application.</p></div><div className="searchLarge"><Search size={19}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search schools..."/></div><div className="directoryGrid">{schools.map(s=><article className="directoryCard" key={s.id}><img className="schoolPhoto" src={s.image||schoolImage(s.name)} alt={s.name}/><div className="schoolBadge"><School size={22}/></div><span className="status approved">APPROVED</span><h3>{s.name}</h3><p>Centre Number {s.centre} • {s.location}</p><p className="schoolDetailLine">{s.address||s.location} • {s.phone||"School contact available on request"}</p><div className="directoryMeta"><span>{s.type}</span><b>{totalSpaces(s.spaces)} spaces</b></div><button className="outlineButton full" onClick={()=>setPage("login")}>Login to Apply <ArrowRight size={16}/></button></article>)}</div></section></div>}

function Page({page,user,data,update,setPage}){switch(page){case"overview":return <Overview user={user} data={data} setPage={setPage}/>;case"schools":return <ParentSchools user={user} data={data} setPage={setPage}/>;case"applications":return user.role==="Parent"?<ParentApplications user={user} data={data} update={update}/>:<Admissions user={user} data={data} update={update}/>;case"students":return <Students user={user} data={data}/>;case"staff":return <Staff user={user} data={data} update={update}/>;case"attendance":return user.role==="Parent"?<ParentAttendance user={user} data={data}/>:<Attendance user={user} data={data} update={update}/>;case"marks":return user.role==="Parent"?<ParentMarks user={user} data={data}/>:<Marks user={user} data={data} update={update}/>;case"finance":return <Finance user={user} data={data} update={update}/>;case"spaces":return <Spaces user={user} data={data}/>;case"calendar":return <CalendarPage user={user} data={data} update={update}/>;case"notifications":return <Notifications user={user} data={data} update={update}/>;case"children":return <Children user={user} data={data}/>;case"fees":return <ParentFees user={user} data={data}/>;case"feedback":return <ParentFeedback user={user} data={data} update={update}/>;case"settings":return <SettingsPage/>;default:return <Overview user={user} data={data} setPage={setPage}/>}}

function Shell({eyebrow,title,text,action,children}){return <><div className="pageHead"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{text}</p></div>{action}</div>{children}</>}
function Card({title,children,action}){return <section className="card"><div className="cardHead"><h3>{title}</h3>{action}</div>{children}</section>}
function Empty({text}){return <div className="empty"><FileText size={25}/><p>{text}</p></div>}
function Status({value}){return <span className={'status '+value.toLowerCase()}>{value}</span>}

function Overview({user,data,setPage}){const school=user.schoolId?data.schools.find(s=>s.id===user.schoolId):null;const ownStudents=user.role==="Parent"?data.students.filter(s=>s.parentEmail===user.email):school?data.students.filter(s=>s.schoolId===school.id):[];let stats=[];if(user.role==="System Admin")stats=[["Registered schools",data.schools.length,"schools"],["Pending schools",data.pendingSchools.length,"awaiting verification"],["Approved",data.schools.filter(s=>s.status==="APPROVED").length,"live schools"]];else if(user.role==="Parent")stats=[["My children",ownStudents.length,"linked children"],["Applications",data.applications.filter(a=>a.parentEmail===user.email).length,"submitted"],["Notifications",data.notifications.length,"available"]];else if(user.role==="Accountant")stats=[["Students",school?data.students.filter(s=>s.schoolId===school.id).length:0,"fee records"],["Pending receipts",data.payments.filter(p=>p.status==="PENDING").length,"to review"],["Paid in demo",`E${data.payments.filter(p=>p.status==="APPROVED").reduce((a,p)=>a+p.amount,0).toLocaleString()}`,"approved payments"]];else stats=[["Students",school?data.students.filter(s=>s.schoolId===school.id).length:0,"registered"],["Applications",school?data.applications.filter(a=>a.schoolId===school.id&&a.status==="PENDING").length:0,"active"],["School events",data.calendar.length,"calendar items"]];return <Shell eyebrow="PORTAL OVERVIEW" title={`Welcome, ${user.name.split(" ")[0]}`} text={school?`${user.role} access for ${school.name}.`:`${user.role} platform administration.`}><div className="statGrid">{stats.map(([a,b,c])=><div className="statCard" key={a}><span>{a}</span><b>{b}</b><small>{c}</small></div>)}</div><div className="overviewGrid"><Card title="Your responsibilities"><ul className="taskList">{responsibilities(user.role).map(x=><li key={x[0]}><span>{x[1]}</span><button onClick={()=>setPage(x[0])}>Open <ArrowRight size={14}/></button></li>)}</ul></Card><Card title="Access principle"><div className="accessBox"><ShieldCheck size={25}/><div><b>Information is role-limited</b><p>Parents only see their own children. Teachers only edit the subjects and forms assigned to them. Accountants handle fees, while the System Admin handles platform school approval.</p></div></div></Card></div></Shell>}
function responsibilities(role){const m={"System Admin":[["schools","Verify and approve school registrations"],["settings","Platform settings"]],Principal:[["applications","Review admissions"],["marks","Review school marks"],["staff","Manage staff"],["finance","Review school fees"]],"Deputy Principal":[["applications","Review admissions"],["marks","Review marks"],["staff","Manage staff"]],Teacher:[["students","View student table"],["marks","Enter assigned subject marks"],["attendance","Update attendance"]],Accountant:[["finance","Review balances and receipts"]],Secretary:[["notifications","Send school notifications"],["calendar","Manage calendar"]],Parent:[["schools","Find a school"],["applications","Apply with documents"],["children","View my children"]]};return m[role]||[]}

function ParentSchools({user,data,setPage}){const [q,setQ]=useState("");const list=data.schools.filter(s=>s.status==="APPROVED"&&(`${s.name} ${s.centre} ${s.location}`.toLowerCase().includes(q.toLowerCase())));return <Shell eyebrow="SCHOOL DIRECTORY" title="Find a school" text="You are already signed in. There is no second parent login. Select a school to start an application."><div className="searchLarge"><Search size={19}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="School name, Centre Number or location"/></div><div className="directoryGrid">{list.map(s=><article className="directoryCard" key={s.id}><img className="schoolPhoto" src={s.image||schoolImage(s.name)} alt={s.name}/><div className="schoolBadge"><School size={22}/></div><Status value="APPROVED"/><h3>{s.name}</h3><p>Centre {s.centre} • {s.location}</p><p className="schoolDetailLine">{s.address||s.location} • {s.phone||"School contact available on request"}</p><div className="directoryMeta"><span>{s.type}</span><b>{totalSpaces(s.spaces)} spaces</b></div><button className="goldButton full" onClick={()=>setPage("applications")}>Apply to this school <ArrowRight size={16}/></button></article>)}</div></Shell>}

function ParentApplications({user,data,update}){const own=data.applications.filter(a=>a.parentEmail===user.email);const [form,setForm]=useState({schoolId:"",childName:"",form:"Form 1",documents:[]});const [files,setFiles]=useState([]);const submit=()=>{if(!form.schoolId||!form.childName){alert("Select a school and enter the child's name.");return}const app={id:"A"+Date.now(),parentEmail:user.email,parentName:user.name,schoolId:form.schoolId,childName:form.childName,form:form.form,status:"PENDING",documents:files.map((name)=>({name})),submitted:new Date().toLocaleDateString()};update({...data,applications:[...data.applications,app]});setForm({...form,childName:"",schoolId:""});setFiles([]);alert("Application submitted. The school's responsible approver can now see it.")};return <Shell eyebrow="ADMISSIONS" title="My applications" text="Only parents submit applications. Required supporting documents can be attached before submission."><Card title="New application"><div className="twoCol"><label>Desired school<select value={form.schoolId} onChange={e=>setForm({...form,schoolId:e.target.value})}><option value="">Select school</option>{data.schools.filter(s=>s.status==="APPROVED"&&s.admission==="OPEN").map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Child full name<input value={form.childName} onChange={e=>setForm({...form,childName:e.target.value})}/></label><label>Grade / Form<select value={form.form} onChange={e=>setForm({...form,form:e.target.value})}><option>Form 1</option><option>Form 2</option><option>Form 3</option><option>Form 4</option><option>Form 5</option></select></label></div><label className="uploadBox"><Upload size={21}/><span><b>Upload required documents</b><small>Transcript, birth certificate or other school-required documents.</small></span><input type="file" multiple onChange={e=>setFiles(Array.from(e.target.files||[]).map(f=>f.name))}/></label>{files.length>0&&<div className="fileList">{files.map(f=><span key={f}><FileText size={14}/>{f}</span>)}</div>}<button className="goldButton" onClick={submit}>Submit application <ArrowRight size={16}/></button></Card><Card title="Application history">{own.length?<Table headers={["School","Child","Form","Documents","Status"]} rows={own.map(a=>[data.schools.find(s=>s.id===a.schoolId)?.name||"Unknown",a.childName,a.form,(a.documents||[]).length, <Status value={a.status}/>])}/>:<Empty text="No applications yet."/>}</Card></Shell>}

function Admissions({user,data,update}){const list=data.applications.filter(a=>a.schoolId===user.schoolId);const decide=(id,status)=>{let next={...data,applications:data.applications.map(a=>a.id===id?{...a,status}:a)};const app=data.applications.find(a=>a.id===id);if(status==="APPROVED"&&app){const school=data.schools.find(s=>s.id===user.schoolId);if(school&&Number(school.spaces[app.form]||0)>0)next.schools=data.schools.map(s=>s.id===school.id?{...s,spaces:{...s.spaces,[app.form]:Math.max(0,Number(s.spaces[app.form])-1)}}:s);else{alert("No available space for this grade/form.");return}}update(next)};return <Shell eyebrow="ADMISSIONS" title="Application management" text="Review active applications and approve, decline or wait-list them. Parent submissions appear here automatically."><Card title="Applications">{list.length?<Table headers={["Applicant","Child","Form","Documents","Status","Decision"]} rows={list.map(a=>[a.parentName,a.childName,a.form,<button className="smallButton" onClick={()=>alert((a.documents||[]).map(d=>d.name).join("\n")||"No documents")}>View</button>,<Status value={a.status}/>,a.status==="PENDING"?<div className="actionsRow"><button className="smallButton success" onClick={()=>decide(a.id,"APPROVED")}>Approve</button><button className="smallButton" onClick={()=>decide(a.id,"WAITLIST")}>Wait list</button><button className="smallButton danger" onClick={()=>decide(a.id,"DECLINED")}>Decline</button></div>:"Processed"])}/>:<Empty text="No applications yet. When a parent applies to this school, the application will appear here."/>}</Card></Shell>}

function Students({user,data}){const list=data.students.filter(s=>s.schoolId===user.schoolId);const forms=[...new Set(list.map(s=>s.form))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));return <Shell eyebrow="STUDENT REGISTER" title="Students" text="Students are displayed in separate tables for each Grade/Form, with attendance and average performance.">{forms.map(form=>{const rows=list.filter(s=>s.form===form);return <Card key={form} title={form}><Table headers={["Name","Attendance","Average","Status"]} rows={rows.map(s=>[s.name,`${s.attendance}%`,`${average(s)}%`,average(s)<50?<span className="dangerText">Needs attention</span>:<span className="goodText">On track</span>])}/></Card>})}</Shell>}
function Staff({user,data,update}){const school=data.schools.find(s=>s.id===user.schoolId);const [form,setForm]=useState({name:"",role:"Teacher",email:"",subjects:"",grades:"",classTeacherForms:""});if(!school)return <Empty text="No school assigned."/>;const add=()=>{if(!form.name||!form.email){alert("Name and email are required.");return}const staff={id:"T"+Date.now(),name:form.name,role:form.role,email:form.email,phone:"",photo:staffImage(form.name),subjects:form.subjects.split(",").map(x=>x.trim()).filter(Boolean),grades:form.grades.split(",").map(x=>x.trim()).filter(Boolean),classTeacherForms:form.classTeacherForms.split(",").map(x=>x.trim()).filter(Boolean)};update({...data,schools:data.schools.map(s=>s.id===school.id?{...s,staff:[...s.staff,staff]}:s)});setForm({name:"",role:"Teacher",email:"",subjects:"",grades:"",classTeacherForms:""})};const remove=(id)=>update({...data,schools:data.schools.map(s=>s.id===school.id?{...s,staff:s.staff.filter(x=>x.id!==id)}:s)});return <Shell eyebrow="STAFF" title="Staff management" text="The principal and deputy principal can add or remove school staff when staff members join or leave the school."><Card title="Add staff"><div className="twoCol"><label>Name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Email<input value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Role<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}>{["Teacher","Principal","Deputy Principal","Accountant","Secretary"].map(x=><option key={x}>{x}</option>)}</select></label><label>Subjects (teachers)<input value={form.subjects} onChange={e=>setForm({...form,subjects:e.target.value})}/></label><label>Grades / Forms taught<input value={form.grades} onChange={e=>setForm({...form,grades:e.target.value})}/></label><label>Class teacher Forms<input value={form.classTeacherForms} onChange={e=>setForm({...form,classTeacherForms:e.target.value})} placeholder="e.g. Form 1"/></label></div><button className="goldButton" onClick={add}><Plus size={17}/> Add staff</button></Card><Card title="Registered staff"><div className="staffProfileGrid">{school.staff.map(s=><article className="staffProfileCard" key={s.id}><img className="staffPhoto" src={s.photo||staffImage(s.name)} alt={s.name}/><div className="staffProfileBody"><h3>{s.name}</h3><span className="status approved">{s.role}</span><p><b>Email:</b> {s.email||"—"}</p><p><b>Phone:</b> {s.phone||"—"}</p>{s.role==="Teacher"&&<><p><b>Subjects:</b> {(s.subjects||[]).join(", ")||"—"}</p><p><b>Grades/Forms:</b> {(s.grades||[]).join(", ")||"—"}</p><p><b>Class teacher:</b> {(s.classTeacherForms||[]).join(", ")||"—"}</p></>}<button className="smallButton danger" onClick={()=>remove(s.id)}><Trash2 size={14}/> Remove</button></div></article>)}</div></Card></Shell>}

function Attendance({user,data,update}){  const school=data.schools.find(s=>s.id===user.schoolId);  const classTeacherForms=user.role==="Teacher"?(user.classTeacherForms||[]):[];  const canMark=user.role==="Teacher"&&classTeacherForms.length>0;  const students=school?data.students.filter(s=>s.schoolId===school.id&&(canMark?classTeacherForms.includes(s.form):true)):[];  const date=todayKey();  const records=data.attendanceRecords||{};  const todayRecords=records[date]||{};  const absentCount=students.filter(s=>todayRecords[s.id]==="ABSENT").length;  const markAbsent=(studentId)=>{if(!canMark)return;const nextRecords={...records,[date]:{...todayRecords,[studentId]:"ABSENT"}};update({...data,attendanceRecords:nextRecords});};  return <Shell eyebrow="ATTENDANCE" title="Student register" text={canMark?`You can mark absent students only for your class-teacher Form(s): ${classTeacherForms.join(", ")}.`:"The register is view-only for this role. Only the class teacher assigned to a Form can mark that class register."}>    <div className="statGrid"><div className="statCard"><span>Class teacher Form</span><b>{canMark?classTeacherForms.join(", "):"View only"}</b><small>{canMark?"Only your assigned class register":"No register editing access"}</small></div><div className="statCard"><span>Total absent</span><b>{absentCount}</b><small>today</small></div><div className="statCard"><span>Total students</span><b>{students.length}</b><small>{date}</small></div></div>    <Card title={canMark?"Class register — mark absent only":"Attendance register — view only"}>      {students.length?<Table headers={["Grade/Form","Student","Attendance Rate","Today"]} rows={students.map(s=>[s.form,s.name,`${s.attendance}%`,canMark?(todayRecords[s.id]==="ABSENT"?<Status value="ABSENT"/>:<button className="smallButton danger" onClick={()=>markAbsent(s.id)}>Mark absent</button>):(todayRecords[s.id]==="ABSENT"?<Status value="ABSENT"/>:<Status value="PRESENT"/>)])}/>:<Empty text={canMark?"No students are assigned to your class-teacher Form.":"No students found."}/>}    </Card>  </Shell>;}function ParentAttendance({user,data}){const list=data.students.filter(s=>s.parentEmail===user.email);return <Shell eyebrow="MY CHILDREN" title="Attendance" text="Only your children's attendance is visible. School-wide attendance and the school register are hidden."><Card title="My children's attendance">{list.length?<Table headers={["Child","Grade/Form","Attendance"]} rows={list.map(s=>[s.name,s.form,`${s.attendance}%`])}/>:<Empty text="No accepted child is linked to this parent account yet."/>}</Card></Shell>}

function Marks({user,data,update}){
  const school=data.schools.find(s=>s.id===user.schoolId);
  const allSubjects=["Mathematics","English","Chemistry","Agriculture","Physics"];
  const isTeacher=user.role==="Teacher";
  const isLeadership=user.role==="Principal"||user.role==="Deputy Principal";
  const classTeacherForms=user.classTeacherForms||[];
  const taughtForms=user.grades||[];
  const editableForms=taughtForms.filter(form=>!classTeacherForms.includes(form));
  const schoolStudents=data.students.filter(s=>s.schoolId===user.schoolId);
  const classTeacherStudents=schoolStudents.filter(s=>classTeacherForms.includes(s.form));
  const subjectStudents=schoolStudents.filter(s=>editableForms.includes(s.form));
  const overallAverage=schoolStudents.length?Math.round(schoolStudents.reduce((sum,s)=>sum+average(s),0)/schoolStudents.length):0;
  const classAverage=(form)=>{const rows=schoolStudents.filter(s=>s.form===form);return rows.length?Math.round(rows.reduce((sum,s)=>sum+average(s),0)/rows.length):0};
  const updateSubject=(sid,subject,patch)=>{
    const nextStudents=data.students.map(s=>{
      if(s.id!==sid)return s;
      const current=s.subjects?.[subject]||{test:0,exam:0,comment:""};
      return {...s,subjects:{...s.subjects,[subject]:{...current,...patch}}};
    });
    update({...data,students:nextStudents});
  };
  const teacherPerformance=school?.staff.filter(s=>s.role==="Teacher").flatMap(t=>(t.subjects||[]).map(subject=>{
    const taught=(t.grades||[]).flatMap(form=>schoolStudents.filter(st=>st.form===form&&st.subjects?.[subject]));
    const vals=taught.flatMap(st=>{const m=st.subjects[subject];return [Number(m.test||0),Number(m.exam||0)]});
    return {name:t.name,subject,average:vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0};
  }))||[];
  const renderTable=(students,subjects,mode)=> <div className="tableScroll"><table className="marksTable"><thead><tr><th>Form</th><th>Name</th>{subjects.map(subject=><th key={subject}>{subject}<small>Test / Exam / Comment</small></th>)}<th>Aggregate</th></tr></thead><tbody>{students.map(st=><tr key={st.id}>{<><td>{st.form}</td><td><b>{st.name}</b></td>{subjects.map(subject=>{const m=st.subjects?.[subject]||{test:0,exam:0,comment:""};const canEdit=isTeacher&&mode==="subject"&&(user.subjects||[]).includes(subject)&&editableForms.includes(st.form);const canComment=isLeadership||(isTeacher&&canEdit);const commentValue=isLeadership?(m.leadershipComment||""):(m.teacherComment||m.comment||"");return <td key={subject}><div className="markPair"><input disabled={!canEdit} type="number" min="0" max="100" value={m.test} onChange={e=>updateSubject(st.id,subject,{test:Math.max(0,Math.min(100,Number(e.target.value)))})}/><input disabled={!canEdit} type="number" min="0" max="100" value={m.exam} onChange={e=>updateSubject(st.id,subject,{exam:Math.max(0,Math.min(100,Number(e.target.value)))})}/></div>{canComment?<textarea className="markComment" value={commentValue} placeholder={isLeadership?"Leadership comment":"Teacher comment"} onChange={e=>updateSubject(st.id,subject,isLeadership?{leadershipComment:e.target.value}:{teacherComment:e.target.value})}/>:commentValue?<div className="commentReadOnly">{commentValue}</div>:null}</td>})}<td><b>{aggregate(st)}</b></td></>}</tr>)}</tbody></table></div>;
  return <Shell eyebrow="ACADEMICS" title="Marks & Performance" text={isTeacher?"Your access separates class-teacher viewing from subject-teaching permissions. Class-teacher Forms are view-only; taught subjects in other Forms can be edited and commented on.":"Leadership can review all student marks in table form, comment on students without altering marks, and review school, class and teacher-subject performance."}>
    {isTeacher&&<div className="statGrid">{classTeacherForms.map(form=><div className="statCard" key={form}><span>{form} class aggregate</span><b>{classAverage(form)}%</b><small>view-only class-teacher performance</small></div>)}{editableForms.map(form=><div className="statCard" key={form}><span>{form} subject average</span><b>{classAverage(form)}%</b><small>subjects you teach only</small></div>)}</div>}
    {isLeadership&&<div className="statGrid"><div className="statCard"><span>Overall school performance</span><b>{overallAverage}%</b><small>average across all school students</small></div>{[...new Set(schoolStudents.map(s=>s.form))].map(form=><div className="statCard" key={form}><span>{form} performance</span><b>{classAverage(form)}%</b><small>overall class/Form average</small></div>)}</div>}
    {isTeacher&&classTeacherStudents.length>0&&<Card title="Class teacher view — full class marks (view only)">{renderTable(classTeacherStudents,allSubjects,"class")}</Card>}
    {isTeacher&&subjectStudents.length>0&&<Card title="Subject teaching view — editable subjects only">{renderTable(subjectStudents,user.subjects||[],"subject")}</Card>}
    {isTeacher&&!classTeacherStudents.length&&!subjectStudents.length&&<Card title="Marks"><Empty text="No students are assigned to your current class-teacher or subject-teaching Forms."/></Card>}
    {isLeadership&&<Card title="School marks overview">{renderTable(schoolStudents,allSubjects,"leadership")}</Card>}
    {isTeacher&&<Card title="Your access summary"><p className="muted">Class teacher Forms: <b>{classTeacherForms.join(", ")||"None"}</b>. Subjects you teach: <b>{(user.subjects||[]).join(", ")||"None"}</b>. Editable teaching Forms: <b>{editableForms.join(", ")||"None"}</b>.</p></Card>}
    {isLeadership&&<Card title="Teacher performance by subject"><Table headers={["Teacher","Subject","Average"]} rows={teacherPerformance.map(x=>[x.name,x.subject,`${x.average}%`])}/></Card>}
  </Shell>;
}

function ParentMarks({user,data}){const list=data.students.filter(s=>s.parentEmail===user.email&&s.schoolId===user.schoolId);return <Shell eyebrow="MY CHILDREN" title="Marks & performance" text="Only accepted children linked to your account are shown here. Teacher, Principal and Deputy Principal comments about your child are also visible."><Card title="Academic record">{list.length?<div className="tableScroll"><table className="marksTable"><thead><tr><th>Child</th><th>Form</th><th>Subject</th><th>Test</th><th>Exam</th><th>Aggregate</th><th>Teacher comment</th><th>Leadership comment</th></tr></thead><tbody>{list.flatMap(s=>Object.entries(s.subjects||{}).map(([subject,m])=><tr key={s.id+subject}><td>{s.name}</td><td>{s.form}</td><td>{subject}</td><td>{m.test}</td><td>{m.exam}</td><td>{Number(m.test||0)+Number(m.exam||0)}</td><td>{m.teacherComment||m.comment||"—"}</td><td>{m.leadershipComment||"—"}</td></tr>))}</tbody></table></div>:<Empty text="A child's academic record becomes visible after the child is accepted and linked to this parent."/>}</Card></Shell>}
function ParentFeedback({user,data,update}){const isParent=user.role==="Parent";const teachers=(data.schools.find(s=>s.id===user.schoolId)?.staff||[]).filter(s=>s.role==="Teacher");const feedback=data.parentFeedback||[];const suggestions=data.suggestions||[];const [teacherId,setTeacherId]=useState("");const [comment,setComment]=useState("");const [suggestion,setSuggestion]=useState("");const submitComment=()=>{if(!isParent||!teacherId||!comment.trim())return;const teacher=teachers.find(t=>t.id===teacherId);update({...data,parentFeedback:[...feedback,{id:"PF"+Date.now(),parentEmail:user.email,parentName:user.name,teacherId,teacherName:teacher?.name||"Teacher",comment:comment.trim(),date:todayKey(),schoolId:user.schoolId}]});setComment("");setTeacherId("")};const submitSuggestion=()=>{if(!isParent||!suggestion.trim())return;update({...data,suggestions:[...suggestions,{id:"SG"+Date.now(),parentEmail:user.email,parentName:user.name,suggestion:suggestion.trim(),date:todayKey(),schoolId:user.schoolId}]});setSuggestion("")};return <Shell eyebrow="PARENT VOICE" title="Parent feedback & suggestions" text={isParent?"Share feedback about a teacher and submit suggestions to school leadership.":"Only the Principal and Deputy Principal can view parent feedback and suggestions."}>{isParent?<><Card title="Comment about a teacher"><label>Teacher<select value={teacherId} onChange={e=>setTeacherId(e.target.value)}><option value="">Select teacher</option>{teachers.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label><label>Comment<textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="Write your comment about the teacher..."/></label><button className="goldButton" onClick={submitComment}>Submit teacher comment <ArrowRight size={16}/></button></Card><Card title="Suggestion box"><label>Suggestion<textarea value={suggestion} onChange={e=>setSuggestion(e.target.value)} placeholder="Share a suggestion for improving the school..."/></label><button className="goldButton" onClick={submitSuggestion}>Submit suggestion <ArrowRight size={16}/></button></Card><Card title="My submitted feedback"><Table headers={["Type","Details","Date"]} rows={[...feedback.filter(x=>x.parentEmail===user.email).map(x=>["Teacher comment",`${x.teacherName}: ${x.comment}`,x.date]),...suggestions.filter(x=>x.parentEmail===user.email).map(x=>["Suggestion",x.suggestion,x.date])]}/></Card></>:<><Card title="Parent comments about teachers"><Table headers={["Parent","Teacher","Comment","Date"]} rows={feedback.filter(x=>x.schoolId===user.schoolId).map(x=>[x.parentName,x.teacherName,x.comment,x.date])}/></Card><Card title="Parent suggestion box"><Table headers={["Parent","Suggestion","Date"]} rows={suggestions.filter(x=>x.schoolId===user.schoolId).map(x=>[x.parentName,x.suggestion,x.date])}/></Card></>}</Shell>}

function Finance({user,data,update}){const list=data.students.filter(s=>s.schoolId===user.schoolId);const canApprove=user.role==="Accountant";const approve=(id)=>{if(!canApprove)return;update({...data,payments:data.payments.map(p=>p.id===id?{...p,status:"APPROVED"}:p)})};return <Shell eyebrow="FINANCE" title="School fees" text={canApprove?"Accountants manage fee balances and verify parent-submitted receipts. Academic performance is not shown in this area.":"Finance is view-only for school leadership. You can review balances and receipts but cannot alter financial records."}><Card title="Fee ledger"><Table headers={["Form","Student","School fee","Paid","Balance","Receipt status"]} rows={list.map(s=>{const school=data.schools.find(x=>x.id===s.schoolId);const paid=data.payments.filter(p=>p.studentId===s.id&&p.status==="APPROVED").reduce((a,p)=>a+p.amount,0);const pending=data.payments.filter(p=>p.studentId===s.id&&p.status==="PENDING");return [s.form,s.name,`E${Number(school?.fees||0).toLocaleString()}`,`E${paid.toLocaleString()}`,`E${Math.max(0,Number(school?.fees||0)-paid).toLocaleString()}`,pending.length?<div className="actionsRow"><Status value="PENDING"/>{canApprove&&<button className="smallButton success" onClick={()=>approve(pending[0].id)}>Approve receipt</button>}</div>:<Status value="APPROVED"/>]})}/></Card><Card title="Submitted receipts"><Table headers={["Student","Receipt","Amount","Status","Action"]} rows={data.payments.filter(p=>p.parentEmail).map(p=>[data.students.find(s=>s.id===p.studentId)?.name||"Unknown",p.receipt,`E${p.amount.toLocaleString()}`,<Status value={p.status}/>,p.status==="PENDING"&&canApprove?<button className="smallButton success" onClick={()=>approve(p.id)}>Approve</button>:p.status==="PENDING"?"View only":"Verified"])}/></Card></Shell>}

function ParentFees({user,data}){const list=data.students.filter(s=>s.parentEmail===user.email);return <Shell eyebrow="MY CHILDREN" title="School fees" text="View only the fee records belonging to your children."><Card title="Fee balances">{list.length?<Table headers={["Child","School","Fee","Paid","Balance"]} rows={list.map(s=>{const school=data.schools.find(x=>x.id===s.schoolId);const paid=data.payments.filter(p=>p.studentId===s.id&&p.status==="APPROVED").reduce((a,p)=>a+p.amount,0);return [s.name,school?.name||"—",`E${Number(school?.fees||0).toLocaleString()}`,`E${paid.toLocaleString()}`,`E${Math.max(0,Number(school?.fees||0)-paid).toLocaleString()}`]})}/>:<Empty text="No accepted child is linked to this parent account."/>}</Card></Shell>}

function Spaces({user,data,update}){  const school=data.schools.find(s=>s.id===user.schoolId);  const canEdit=user.role==="Principal"||user.role==="Deputy Principal";  const setSpace=(grade,value)=>{if(!canEdit||!school)return;const safe=Math.max(0,Number(value)||0);update({...data,schools:data.schools.map(s=>s.id===school.id?{...s,spaces:{...s.spaces,[grade]:safe}}:s)});};  return <Shell eyebrow="ADMISSIONS CAPACITY" title="Available spaces" text={canEdit?"The Principal and Deputy Principal are responsible for maintaining available Grade/Form spaces. Changes are immediately reflected in the school directory and application workflow.":"Available Grade/Form spaces are displayed here. Only the Principal and Deputy Principal can change capacity information."}>    <Card title={school?.name||"School"}><div className="spaceGrid">{Object.entries(school?.spaces||{}).map(([g,n])=><div key={g}><span>{g}</span>{canEdit?<input className="inlineInput" type="number" min="0" value={n} onChange={e=>setSpace(g,e.target.value)}/>:<b>{n}</b>}<small>available</small></div>)}</div></Card>  </Shell>;}function CalendarPage({user,data,update}){const canAdd=["Principal","Deputy Principal","Secretary"].includes(user.role);const [form,setForm]=useState({title:"",date:"",time:"",details:""});const add=()=>{if(!form.title||!form.date)return;update({...data,calendar:[...data.calendar,{...form,id:"C"+Date.now()}]});setForm({title:"",date:"",time:"",details:""})};return <Shell eyebrow="SCHOOL CALENDAR" title="Calendar" text="School calendar events are shared with the roles who have calendar access.">{canAdd&&<Card title="Add event"><div className="twoCol"><label>Event title<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Date<input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Time<input type="time" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></label><label>Details<input value={form.details} onChange={e=>setForm({...form,details:e.target.value})}/></label></div><button className="goldButton" onClick={add}><Plus size={16}/> Add event</button></Card>}<Card title="Upcoming events"><Table headers={["Date","Time","Event","Details"]} rows={data.calendar.map(c=>[c.date,c.time,c.title,c.details])}/></Card></Shell>}
function Notifications({user,data,update}){const canSend=["Principal","Deputy Principal","Secretary"].includes(user.role);const [form,setForm]=useState({title:"",body:""});const send=()=>{if(!form.title||!form.body)return;update({...data,notifications:[...data.notifications,{id:"N"+Date.now(),...form,audience:"school"}]});setForm({title:"",body:""})};return <Shell eyebrow="COMMUNICATIONS" title="Notifications" text="School notifications such as fee reminders, meetings and announcements can be published by authorised school staff.">{canSend&&<Card title="Create notification"><label>Title<input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>Message<textarea value={form.body} onChange={e=>setForm({...form,body:e.target.value})}/></label><button className="goldButton" onClick={send}>Send notification <ArrowRight size={16}/></button></Card>}<Card title="Notifications">{data.notifications.map(n=><div className="notification" key={n.id}><span className="notificationIcon"><Bell size={18}/></span><div><b>{n.title}</b><p>{n.body}</p><small>SMS integration can be connected in production.</small></div></div>)}</Card></Shell>}
function Children({user,data}){const children=data.students.filter(s=>s.parentEmail===user.email);return <Shell eyebrow="MY CHILDREN" title="My children" text="Only children linked to your parent account are displayed. School-wide student information is not accessible."><Card title="Linked children">{children.length?<Table headers={["Name","Form","Attendance","Average"]} rows={children.map(s=>[s.name,s.form,`${s.attendance}%`,`${average(s)}%`])}/>:<Empty text="No accepted child is currently linked to this parent account."/>}</Card></Shell>}

function AdminSchools({data,update}){const pending=data.pendingSchools;const approve=(school)=>update({...data,pendingSchools:data.pendingSchools.filter(s=>s.id!==school.id),schools:[...data.schools,{...school,status:"APPROVED",admission:"OPEN",spaces:school.spaces&&Object.keys(school.spaces).length?school.spaces:{"Form 1":0,"Form 2":0,"Form 3":0,"Form 4":0,"Form 5":0}}]});const reject=(school)=>update({...data,pendingSchools:data.pendingSchools.filter(s=>s.id!==school.id)});return <Shell eyebrow="PLATFORM ADMINISTRATION" title="School management" text="The System Admin checks whether a school exists and whether submitted information is truthful before approval. Admin does not manage academic performance, applications or fees."><div className="statGrid"><div className="statCard"><span>Pending schools</span><b>{pending.length}</b><small>awaiting verification</small></div><div className="statCard"><span>Registered schools</span><b>{data.schools.length}</b><small>approved schools</small></div><div className="statCard"><span>Total spaces</span><b>{data.schools.reduce((a,s)=>a+totalSpaces(s.spaces),0)}</b><small>directory capacity</small></div></div><Card title="Pending school registrations">{pending.length?<Table headers={["School","Centre","Location","Leadership","Staff","Verification"]} rows={pending.map(s=>[s.name,s.centre,s.location,<div>{s.staff.filter(x=>x.role!=="Teacher").map(x=><div key={x.id}>{x.role}: {x.name}</div>)}</div>,s.staff.length,<div className="actionsRow"><button className="smallButton success" onClick={()=>approve(s)}><Check size={14}/> Approve</button><button className="smallButton danger" onClick={()=>reject(s)}><XCircle size={14}/> Reject</button></div>])}/>:<Empty text="No pending school registrations."/>}</Card><Card title="Approved schools"><Table headers={["School","Centre","Location","Status","Staff"]} rows={data.schools.map(s=>[s.name,s.centre,s.location,<Status value="APPROVED"/>,s.staff.length])}/></Card></Shell>}
function SettingsPage(){return <Shell eyebrow="PLATFORM" title="Settings" text="Prototype configuration and security principles."><Card title="Access control"><div className="accessBox"><ShieldCheck size={26}/><div><b>Least privilege</b><p>Role permissions are enforced in the interface for this prototype. A production deployment should also enforce the same rules on the backend/database with secure authentication, audit logs and protected document storage.</p></div></div></Card></Shell>}

function Table({headers,rows}){return <div className="tableScroll"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div>}

// Replace the placeholder page handler for admin without adding admin-only navigation items.
const OriginalPage=Page;
function RoutedPage(props){if(props.user.role==="System Admin"&&props.page==="schools")return <AdminSchools data={props.data} update={props.update}/>;return <OriginalPage {...props}/>}

function Root(){const [data,setData]=useState(load);const [user,setUser]=useState(null);const [page,setPage]=useState("home");const [mobile,setMobile]=useState(false);const update=(next)=>{setData(next);save(next)};if(!user)return <Public data={data} update={update} page={page} setPage={setPage} onLogin={setUser}/>;const allowed=roleAccess[user.role]||[];const school=user.schoolId?data.schools.find(s=>s.id===user.schoolId):null;return <div className="portal"><aside className={mobile?"sidebar open":"sidebar"}><div className="logo"><span className="logoMark"><ShieldCheck size={21}/></span><div>EduLink <b>ESWATINI</b></div></div><div className="rolePill"><span></span>{user.role}</div><nav>{allowed.map(key=>{const [label,Icon]=nav[key];return <button key={key} className={page===key?"active":""} onClick={()=>{setPage(key);setMobile(false)}}><Icon size={18}/>{label}</button>})}</nav><div className="sideBottom"><div className="securityNote"><ShieldCheck size={15}/><span>Role-based access enabled</span></div><button className="signout" onClick={()=>{setUser(null);setPage("home")}}><LogOut size={17}/>Sign out</button></div></aside><main className="workspace"><header className="topbar"><button className="mobileMenu" onClick={()=>setMobile(!mobile)}>{mobile?<X/>:<Menu/>}</button><div><span className="crumb">EduLink Eswatini</span><h2>{nav[page]?.[0]||"Overview"}</h2></div><div className="profile"><span className="avatar">{initials(user.name)}</span><div><b>{user.name}</b><small>{user.role}{school?` • ${school.name}`:""}</small></div></div></header><div className="pageArea"><RoutedPage page={page} user={user} data={data} update={update} setPage={setPage}/></div></main></div>}

createRoot(document.getElementById("root")).render(<Root/>);
